sys_script_include.script:
var MSSCustodyBulkUtils = Class.create();
MSSCustodyBulkUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getOwningBusiness: function() { //MSSCUSTODY-3328
        //get owning business for logged-in user
        var owningBusiness = '';
        var grUserOB = new GlideRecord('x_hsb11_mss_c_proc_m2m_sys_user_x_hsb11_mss');
        grUserOB.addQuery('sys_user', gs.getUserID());
        grUserOB.orderBy('x_hsb11_mss_c_proc_custody_location_code.owning_business');
        grUserOB.query();
        if (grUserOB.next()) {
            owningBusiness = grUserOB.x_hsb11_mss_c_proc_custody_location_code.owning_business.toString();
        }

        return owningBusiness;
    },

    getDefaultOwningBusiness: function() {
        // fetching default owning business of user
        var defOwnBus;
        var userOwnBus = new GlideRecord('sys_user');
        userOwnBus.addQuery('sys_id', gs.getUserID());
        userOwnBus.query();

        if (userOwnBus.next()) {
            defOwnBus = userOwnBus.u_default_owning_business.toString();
        }
        if (defOwnBus == 'ALL' || defOwnBus == null || defOwnBus == '') {
            return userOwnBus.u_associated_business_markets.toString();
        }

        return defOwnBus;
    },

    // Amend Validation Logics
    amendValidationChecks: function() {
        var finalCheck = [];
        var notifyUser = [];
        var taskArray = [];
        var tradeDateCheckArray = [];
        var settDateCheckArray = [];
        var scriptHoldIndicatorCheckArray = [];
        cashHoldIndicatorCheckArray = [];
        gdiArrayValueA = [];
        gdiArrayValueM = [];
        scripHoldLinkedTradeArray = [];
        gdiInvalidArray = [];
        var swhMandat = true; //7910

        var bulkid = this.getParameter('sysparm_bulkid');
        var doubleDecimalCurrencies = ['USD', 'EUR', 'GBP'];
        var tripleDecimalCurrencies = ['KWD', 'BHD', 'OMR'];
        var twoDecRegex = /^[0-9]*(\.[0-9]{0,2})?$/;
        var threeDecRegex = /^[0-9]*(\.[0-9]{0,3})?$/;
        var fiveDecRegex = /^[0-9]*(\.[0-9]{0,5})?$/;
        var eightAlphaNumericRegex = /^[a-zA-Z0-9]{8}$/;
        var elevenAlphaNumericRegex = /^[a-zA-Z0-9]{11}$/;
        var twentyFourAlphaNumericRegex = /^[a-zA-Z0-9]{24}$/;
        var fieldRegex = /^[a-zA-Z0-9 ]*$/;
        var accOfClientFieldRegex = /^[a-zA-Z0-9()\/\-?:.,'+ ]+$/;
        var todaysDate = new GlideDate();

        var trdSettlementDate = this.getParameter('sysparm_trdSettlementDate');
        var tskAmendDate = this.getParameter('sysparm_taskAmendDate');
        var trdSettmentCurr = this.getParameter('sysparm_trdSettlementCurr');
        var amendCurr = this.getParameter('sysparm_taskAmendCurr');
        var amendSettAmt = this.getParameter('sysparm_taskAmendSettAmt');
        var amendSettCurrency = this.getParameter('sysparm_amendSettCurrency');
        var amendLocationCode = this.getParameter('sysparm_taskAmendLocationCode');
        //var tradeId = this.getParameter('sysparm_tradeId');
        var amendGdiIndicator = this.getParameter('sysparm_gdiIndicator');
        var placeOfSettlementBic = this.getParameter('sysparm_placeOfSettlementBic');
        var amendScriptHoldIndicator = this.getParameter('sysparm_amendScriptHoldIndicator');
        var amendCashHoldIndicator = this.getParameter('sysparm_amendCashHoldIndicator');
        var amendDelivererReceivererBic = this.getParameter('sysparm_amendDelivererReceivererBic');
        var amendDealPrice = this.getParameter('sysparm_amendDealPrice');
        var amendDealCurrency = this.getParameter('sysparm_amendDealCurrency');
        var trdCashAccId = this.getParameter('sysparm_trdCashAccId');
        var amendBuyerSellerBic = this.getParameter('sysparm_amendBuyerSellerBic');
        var amendCustomerReference = this.getParameter('sysparm_amendCustomerReference');
        var amendSuspenseAccNum = this.getParameter('sysparm_amendSuspenseAccNum');
        var amendSettDate = this.getParameter('sysparm_amendSettDate');
        var amendChargesType = this.getParameter('sysparm_amendChargesType');
        var amendChargesAmt = this.getParameter('sysparm_amendChargesAmt');
        var amendChargesCcy = this.getParameter('sysparm_amendChargesCcy');
        var accOfClient = this.getParameter('sysparm_accOfClient');
        var amendCounterpartySettAccNum = this.getParameter('sysparm_amendCounterpartySettAccNum');
        var amendCounterpartyRef = this.getParameter('sysparm_amendCounterpartyRef');
        // MSSCUSTODY -7133
        var amendReceivererBic = this.getParameter('sysparm_amendReceivererBic');
        var amendSellerBic = this.getParameter('sysparm_amendSellerBic');
        var amendSWH = this.getParameter('sysparm_amendSWH'); //7910

        // MSSCUSTODY-5983
        var amendSecurityID = this.getParameter('sysparm_amendSecurityID');
        var amendCounterpartyCode = this.getParameter('sysparm_amendCounterpartyCode');

        //MSSCUSTODY-8151
        var amendFa = this.getParameter('sysparm_amendFA');

        // MSSCUSTODY-6226
        var securityIDCheckArray = [];
        var counterpartyCodeCheckArray = [];
        var accOfClientCheckArray = [];
        var facheckArrayTorX = [];
        var faNullcheckArray = [];

        notifyUser.push("<a><strong>" + "Please review the below inputs as suggessted to proceed with amendment" + "</strong></a><br\>");

        var gaTaskRec = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
        gaTaskRec.addEncodedQuery('active=true^bulk_id=' + bulkid);
        gaTaskRec.query();
        while (gaTaskRec.next()) {
            var tradeId = gaTaskRec.trade_id;

            var legacy_status = tradeId.legacy_status;
            var legacy_sub_status = tradeId.legacy_sub_status;
            var switch_indicator = tradeId.switch_indicator;
            var owning_business = tradeId.owning_business;
            var counterparty_code = tradeId.counterparty_code;
            var cashHoldIndicator = tradeId.cash_hold_indicator;

            var switchIndi = '';
            switchIndi = tradeId.switch_indicator;
            var locCode = ''; //7910
            locCode = tradeId.location_code;
            var locCodeValue = new GlideRecord('x_hsb11_mss_c_proc_custody_location_code');
            locCodeValue.get(locCode);
            var locCodeDisplayValue = locCodeValue.location_code;

            //Script Hold Indicator Check
            if (amendScriptHoldIndicator != "" && amendScriptHoldIndicator != null) {
                var tradeSettDate = tradeId.settlement_date;
                var linkIndi = tradeId.link_indicator;
                if (amendScriptHoldIndicator == 'S' && (tradeSettDate <= todaysDate) && (owning_business != 'DCC JP' && owning_business != 'DCC AU')) {
                    scriptHoldIndicatorCheckArray.push(gaTaskRec.number.toString());
                } else if (amendScriptHoldIndicator == 'I' && linkIndi == 'Y') {
                    scripHoldLinkedTradeArray.push(gaTaskRec.number.toString());
                }
            }
            //Script Hold Indicator Check

            //Cash Hold Indicator Check
            if (amendCashHoldIndicator != "" && amendCashHoldIndicator != null && (owning_business != 'DCC JP' && owning_business != 'DCC AU')) {
                var tradeSettDate = tradeId.settlement_date;
                if (amendCashHoldIndicator == 'S' && (tradeSettDate <= todaysDate)) {
                    cashHoldIndicatorCheckArray.push(gaTaskRec.number.toString());
                }
            }
            //Cash Hold Indicator Check
            //GDI Check
            // if (amendGdiIndicator != "" && amendGdiIndicator != null) {  Removed as part of MSSCUSTODY-8678
            //     var tradeGDI = tradeId.gdi_indicator;
            //     if (amendGdiIndicator.toString() == 'Manual Generation' && tradeGDI == 'Not Generate') {
            //         gdiArrayValueM.push(gaTaskRec.number.toString());
            //     } else if (amendGdiIndicator.toString() == 'Auto Generation' && (tradeGDI == 'Not Generate' || tradeGDI == 'Manual Generation')) {
            //         gdiArrayValueA.push(gaTaskRec.number.toString());
            //     }
            //     //6621
            //     else 

            if (switchIndi == 'Y' && tradeId.owning_business.indexOf('HK') > -1 && amendGdiIndicator.toString() != 'Not Generate') {
                gdiInvalidArray.push(gaTaskRec.number.toString());
            }

            //SWH Check    //7910
            if (owning_business != 'DCC JP' || locCodeDisplayValue != 'BOJ' || switchIndi != 'Y') {
                swhMandat = false;
            }
            //SWH Check

            // MSSCUSTODY-6226
            var bulk_field_group = this.getParameter('sysparm_bulkFieldGroup');

            if (bulk_field_group == 'security_id') {
                if ((amendSecurityID == '' || amendSecurityID == null) && (legacy_status == 'PRPR' || legacy_status == 'CODE' || (legacy_status == 'PAPP' && legacy_sub_status == 'RCP'))) {
                    securityIDCheckArray.push(gaTaskRec.number.toString() + '');
                }
            }

            if (bulk_field_group == 'counterparty_details') {
                if ((amendCounterpartyCode == '' || amendCounterpartyCode == null) && (legacy_status == 'PRPR' || legacy_status == 'CODE' || (legacy_status == 'PAPP' && legacy_sub_status == 'RCP')) && (switch_indicator == 'N')) {
                    counterpartyCodeCheckArray.push(gaTaskRec.number);
                }
            }

            if (bulk_field_group == 'beneficiary_details') {
                if ((accOfClient == '' || accOfClient == null) && (legacy_status == 'PRPR') && (owning_business == 'DCC HK') && (counterparty_code != '' || counterparty_code != null)) {
                    if (counterparty_code.indexOf('C') == 0) {
                        accOfClientCheckArray.push(gaTaskRec.number);
                    }
                }
            }

            if (bulk_field_group == 'fa') { //MSSCUSTODY-8151
                if (owning_business == 'DCC MY') {
                    if (cashHoldIndicator == 'N' && (amendFa != 'X' && amendFa != 'T')) {
                        facheckArrayTorX.push(gaTaskRec.number);
                    } else if ((cashHoldIndicator == 'I' || cashHoldIndicator == 'S') && amendFa != '') {
                        faNullcheckArray.push(gaTaskRec.number);
                    }
                }

            }
        }

        if (securityIDCheckArray.length > 0) {
            notifyUser.push("Security ID (SEC ID) is a Mandatory field. Please enter a value before submitting. <br\>");
        }

        if (counterpartyCodeCheckArray.length > 0) {
            notifyUser.push("Counterparty Code is a Mandatory field. Please enter a value before submitting. <br\>");
        }

        if (accOfClientCheckArray.length > 0) {
            notifyUser.push("A/c of Client is a Mandatory field. Please enter a value before submitting. <br\>");
        }

        if (facheckArrayTorX.length > 0) {
            notifyUser.push("FA should be selected as 'X' or 'T' if Cash Hold Indicator is 'N'. <br\>");
        }

        if (faNullcheckArray.length > 0) {
            notifyUser.push("FA should be selected as blank if Cash Hold Indicator is 'I' or 'S'. <br\>");
        }
        // if (tradeDateCheckArray != '') {
        //     notifyUser.push(" Trade Date should be lesser than or equal to Trade's settlement date (" + tradeDateCheckArray + ") <br\>");
        //     finalCheck.push('false' + ',');
        // }
        // if (settDateCheckArray != '') {
        //     notifyUser.push(" Settlement Date should be beyond or equal to Trade date (" + settDateCheckArray + ") <br\>");
        //     finalCheck.push('false' + ',');
        // }
        if (scriptHoldIndicatorCheckArray != '') {
            notifyUser.push("Trade's settlement Date should be beyond today's date for value S in Script Hold Indicator  (" + scriptHoldIndicatorCheckArray + ") <br\>");
            finalCheck.push('false' + ',');
        }
        if (scripHoldLinkedTradeArray != '') {
            notifyUser.push("Scrip hold indicator cannot be 'I' if trade has Link Indicator value as 'Y'.  (" + scripHoldLinkedTradeArray + ") <br\>");
            finalCheck.push('false' + ',');
        }
        if (cashHoldIndicatorCheckArray != '') {
            notifyUser.push("Trade's settlement Date should be beyond today's date for value S in Cash Hold Indicator  (" + cashHoldIndicatorCheckArray + ") <br\>");
            finalCheck.push('false' + ',');
        }
        // if (gdiArrayValueM != '') {
        //     notifyUser.push("The GDI Indicator value can not be updated to Manual Generation if trade's GDI Indicator is Not Generate (" + gdiArrayValueM + ") <br\>");
        //     finalCheck.push('false' + ',');
        // }
        // if (gdiArrayValueA != '') {
        //     notifyUser.push("The GDI Indicator value can not be updated to Auto Generation if trade's GDI Indicator is Manual Generation or Not Generate (" + gdiArrayValueA + ") <br\>");
        //     finalCheck.push('false' + ',');
        // }
        //6621
        if (gdiInvalidArray != '') {
            notifyUser.push("The GDI Indicator value can not be Manual Generation or Auto Generation for HK market switching trade (" + gdiInvalidArray + ") <br\>");
            finalCheck.push('false' + ',');
        }

        //Trade Date Check 

        if (tskAmendDate != '' && tskAmendDate != null && amendSettDate != '' && amendSettDate != null) { // MSSCUSTODY-7008 
            //var tradeSettDate = tradeId.settlement_date;
            if (tskAmendDate > amendSettDate) {
                //var taskRec = gaTaskRec.number.toString();
                //tradeDateCheckArray.push(taskRec);
                notifyUser.push(" Trade Date should be less than or equal to Settlement date <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Trade Date Check

        //Settlement Date Check

        if (amendSettDate != '' && amendSettDate != "null" && tskAmendDate != '' && tskAmendDate != null) { // MSSCUSTODY-7008 
            //var tradeDate = tradeId.trade_date;
            if (amendSettDate < tskAmendDate) {
                //settDateCheckArray.push(gaTaskRec.number);
                notifyUser.push(" Settlement Date should be beyond or equal to Trade date <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Settlement Date Check

        //SWH 7910

        if (owning_business == 'DCC JP' && bulk_field_group == 'trade_settl_date' && amendSWH != null && amendSWH != undefined) {
            if (amendSWH == '' && swhMandat == true && (amendSettDate < todaysDate)) {
                notifyUser.push("SWH is mandatory field to submit this bulk. <br\>");
                finalCheck.push('false' + ',');
            } else if (amendSWH != '' && swhMandat == true && (!(amendSettDate < todaysDate))) {
                notifyUser.push("Settlement date should be earlier than today if SWH has a value <br\>");
                finalCheck.push('false' + ',');
            } else if (amendSWH != '' && (swhMandat == false || amendSettDate == '')) {
                notifyUser.push("SWH should be empty to submit this bulk. <br\>");
                finalCheck.push('false' + ',');
            }
        }

        //SWH 7910

        //Customer Reference Check
        if ((amendCustomerReference == "") || (!(accOfClientFieldRegex.test(amendCustomerReference)))) { //updated regex under 7736
            if (legacy_status == 'PAPP' || legacy_status == 'PRPR' || legacy_status == 'CODE' || legacy_status == 'RCP' || legacy_status == 'CONF' || legacy_status == 'CLRG' || legacy_status == 'PCON') {
                notifyUser.push("Customer Reference can not be empty or can not contain special characters. <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Customer Reference Check
        //Place of Settlement (BIC) Check
        if (placeOfSettlementBic != "" && placeOfSettlementBic != null) {
            if ((!(elevenAlphaNumericRegex.test(placeOfSettlementBic)) && !(eightAlphaNumericRegex.test(placeOfSettlementBic)) && (placeOfSettlementBic != 'NA') && (placeOfSettlementBic != 'na'))) {
                notifyUser.push("The Place of Settlement (BIC) should be eight or eleven alphanumeric value <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Place of Settlement (BIC) Check

        //changes under 7133------------START---------//

        //Buyer BIC check

        if (amendBuyerSellerBic != "" && amendBuyerSellerBic != null) {
            if ((!(elevenAlphaNumericRegex.test(amendBuyerSellerBic)) && !(eightAlphaNumericRegex.test(amendBuyerSellerBic))) && (amendBuyerSellerBic != 'NA') && (amendBuyerSellerBic != 'na')) {
                notifyUser.push("The Buyer BIC should be eight or eleven alphanumeric value <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Buyer BIC

        //Seller BIC check

        if (amendSellerBic != "" && amendSellerBic != null) {
            if ((!(elevenAlphaNumericRegex.test(amendSellerBic)) && !(eightAlphaNumericRegex.test(amendSellerBic))) && (amendSellerBic != 'NA') && (amendSellerBic != 'na')) {
                notifyUser.push("The Seller BIC should be eight or eleven alphanumeric value <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Seller BIC

        //Buyer Deliverer Custodian BIC check

        if (amendDelivererReceivererBic != "" && amendDelivererReceivererBic != null) {
            if ((!(elevenAlphaNumericRegex.test(amendDelivererReceivererBic)) && !(eightAlphaNumericRegex.test(amendDelivererReceivererBic))) && (amendDelivererReceivererBic != 'NA') && (amendDelivererReceivererBic != 'na')) {
                notifyUser.push("The Deliverer Custodian BIC should be eight or eleven alphanumeric value <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Buyer Deliverer Custodian BIC check

        //Buyer Receiverer Custodian BIC check

        if (amendReceivererBic != "" && amendReceivererBic != null) {
            if ((!(elevenAlphaNumericRegex.test(amendReceivererBic)) && !(eightAlphaNumericRegex.test(amendReceivererBic))) && (amendReceivererBic != 'NA') && (amendReceivererBic != 'na')) {
                notifyUser.push("The Receiverer Custodian BIC should be eight or eleven alphanumeric value <br\>");
                finalCheck.push('false' + ',');
            }
        }
        //Buyer Receiverer Custodian BIC check

        //changes under 7133------------END---------//

        //Account of Client Check
        if ((accOfClient != "") && (!(accOfClientFieldRegex.test(accOfClient))) && (accOfClient != 'NA') && (accOfClient != 'na')) {
            notifyUser.push("Account of Client can not contain special characters. <br\>");
            finalCheck.push('false' + ',');
        }
        //Account of Client Check

        //Counterparty Reference Check

        if ((amendCounterpartyRef != "") && (!(accOfClientFieldRegex.test(amendCounterpartyRef)))) { //updated regex under 7736
            notifyUser.push("Counterparty Reference can not contain special characters. <br\>");
            finalCheck.push('false' + ',');
        }
        //Counterparty Reference Check

        //Counterparty Settlement Account Number Check
        if ((amendCounterpartySettAccNum != "") && (!(fieldRegex.test(amendCounterpartySettAccNum)))) {
            notifyUser.push("Counterparty Settlement Account Number can not contain special characters. <br\>");
            finalCheck.push('false' + ',');
        }
        //Counterparty Settlement Account Number Check

        //Amend Charges Currency & Amount Mandatory check
        if (amendChargesType == 'U' && (amendChargesAmt == '' || amendChargesCcy == '')) {
            notifyUser.push("The Amend Charges Currency or Amend Charges Amount can not be empty if Amend Charges Type is 'U'. <br\>");
            finalCheck.push('false' + ',');
        }

        //Amend Charges Currency & Amount Mandatory check

        //Amend Charges Amount check

        if (amendChargesAmt != '' && amendChargesCcy != '' && amendChargesAmt != null && amendChargesCcy != null) {
            var curr = new GlideRecord("fx_currency");
            var amendChargesAmt = amendChargesAmt.replace(/[.,]/g, '');
            if ((amendChargesAmt.toString() <= 0) || (!(fieldRegex.test(amendChargesAmt)))) {
                notifyUser.push("Amend Charges Amount can not be zero. <br\>");
                finalCheck.push('false' + ',');
            } else if (curr.get(amendChargesCcy)) {
                var taskCurr = curr.code;
                if (tripleDecimalCurrencies.indexOf(taskCurr.toString()) > -1) {
                    if (!threeDecRegex.test(amendChargesAmt)) {
                        notifyUser.push("Only three decimal values are allowed for " + taskCurr + "<br\>");
                        finalCheck.push('false' + ',');
                    }
                } else if (tripleDecimalCurrencies.indexOf(taskCurr.toString()) <= -1) {
                    if (!twoDecRegex.test(amendChargesAmt)) {
                        notifyUser.push("Only two decimal values are allowed for " + taskCurr + "<br\>");
                        finalCheck.push('false' + ',');
                    }
                }
            }
        }
        //Amend Charges Amount check
        else {
            finalCheck.push('true' + ',');
        }

        // MSSCUSTODY-5983
        var request;
        var responseBody;
        var responseObj;

        if (amendSecurityID != '' && amendSecurityID != null) {
            request = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'instruments');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token'));
            request.setQueryParameter('siteCode', gs.getSession().getClientData('siteCode'));
            request.setQueryParameter('instrumentAlternateGhssIdentifier', amendSecurityID);
            response = request.execute();
            responseBody = response.getBody();
            responseObj = JSON.parse(responseBody);
            if (responseObj.status == '200' && responseObj.data.length == 1) {
                // do nothing
            } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                notifyUser.push("Security ID (SEC ID) (" + amendSecurityID + ") entered is Invalid. <br\>");
            } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                notifyUser.push("There are more than one record for the Security ID (SEC ID) (" + amendSecurityID + ") entered. <br\>");
            } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                notifyUser.push("Unexpected Error at external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
            } else {
                endSleep = new GlideDuration().getNumericValue() + 5000;
                while (new GlideDuration().getNumericValue() < endSleep) {
                    //wait 
                }
                if (responseObj.status == '200' && responseObj.data.length == 0) {
                    notifyUser.push("Security ID (SEC ID) (" + amendSecurityID + ") entered is Invalid. <br\>");
                } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                    notifyUser.push("There are more than one record for the Security ID (SEC ID) (" + amendSecurityID + ") entered. <br\>");
                } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                    notifyUser.push("Unexpected Error at external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
                } else {
                    notifyUser.push("No response received from external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
                }
            }
        }

        if (amendCounterpartyCode != '' && amendCounterpartyCode != null) {
            request = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'counterparties');
            request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token'));
            request.setQueryParameter('siteCode', gs.getSession().getClientData('siteCode'));
            request.setQueryParameter('partyAlternateGhssIdentifier', amendCounterpartyCode);
            response = request.execute();
            responseBody = response.getBody();
            responseObj = JSON.parse(responseBody);
            if (responseObj.status == '200' && responseObj.data.length == 1) {
                // do nothing
            } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                notifyUser.push("Counterparty Code (" + amendCounterpartyCode + ") entered is Invalid. <br\>");
            } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                notifyUser.push("There are more than one record for the Counterparty Code (" + amendCounterpartyCode + ") entered. <br\>");
            } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                notifyUser.push("Unexpected Error at external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
            } else {
                endSleep = new GlideDuration().getNumericValue() + 5000;
                while (new GlideDuration().getNumericValue() < endSleep) {
                    //wait 
                }
                if (responseObj.status == '200' && responseObj.data.length == 0) {
                    notifyUser.push("Counterparty Code (" + amendCounterpartyCode + ") entered is Invalid. <br\>");
                } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                    notifyUser.push("There are more than one record for the Counterparty Code (" + amendCounterpartyCode + ") entered. <br\>");
                } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                    notifyUser.push("Unexpected Error at external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
                } else {
                    notifyUser.push("No response received from external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
                }
            }
        }

        //Trade Decimal Check
        return notifyUser.toString().replaceAll(",", " ");

    },

    //Evaluate Bulk maintenance option.
    evalBulkOptionTradeList: function() { //MSSCUSTODY-3396
        var query = this.getParameter('sysparm_query');
        var bulkOptionField = this.getParameter('sysparm_bulkOptionField');
        var enableBulkOption = false;
        var arrMarket = [];
        var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');

        // fetching associated markets
        var user1 = new GlideRecord('sys_user');
        user1.get(gs.getUserID());
        usermarket = user1.u_associated_business_markets;
        //   var split_market = usermarket.split(',');


        var grTradeDBView = new GlideAggregate('x_hsb11_mss_c_proc_custody_trades');
        grTradeDBView.addEncodedQuery(query);
        grTradeDBView.groupBy('custodytrade_owning_business');
        grTradeDBView.groupBy('custodytrade_trade_lifecycle_status');
        grTradeDBView.query();



        while (grTradeDBView.next()) {

            //Return false if selected task record does not find matching market.
            if (market.indexOf(grTradeDBView.custodytrade_owning_business) == -1) {
                enableBulkOption = false;
                break;
            }


            //Return false if selected trade records are from different markets.
            if (arrMarket.indexOf(grTradeDBView.custodytrade_owning_business.toString()) == -1) {
                arrMarket.push(grTradeDBView.custodytrade_owning_business.toString());
                if (arrMarket.length > 1) {
                    enableBulkOption = false;
                    break;
                }
            }

            //Check BPS table for outcome option 
            var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
            grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTradeDBView.custodytrade_owning_business + '^ctac_code=' + grTradeDBView.custodytrade_trade_lifecycle_status + '^' + bulkOptionField + '=true');
            grBulkEvents.orderBy(bulkOptionField);
            grBulkEvents.query();
            if (grBulkEvents.next()) {
                enableBulkOption = true;
            } else {
                enableBulkOption = false;
                break;
            }

            if (usermarket.indexOf(grTradeDBView.custodytrade_owning_business.toString()) == -1) {
                enableBulkOption = false;
                break;
            }

        }
        return enableBulkOption;

    },

    evalBulkOptionTaskList: function() { //MSSCUSTODY-3493
        //Evaluate eligible bulk option for Task List.
        var query = this.getParameter('sysparm_query');
        var enableBulkOption = true;
        var arrMarket = [];
        var arrTradeLifeCycleStatus = [];
        var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');

        // MSSCUSTODY-6379
        var arrSenderID = [];
        var arrSwiftStatus = ['MT540capture_request', 'MT541capture_request', 'MT542capture_request', 'MT543capture_request', 'MT540cancel_request', 'MT541cancel_request', 'MT542cancel_request', 'MT543cancel_request', 'MT544settlement_confirmation', 'MT545settlement_confirmation', 'MT546settlement_confirmation', 'MT547settlement_confirmation', 'MT544settlement_confirmation_reversal', 'MT545settlement_confirmation_reversal', 'MT546settlement_confirmation_reversal', 'MT547settlement_confirmation_reversal', 'MT548status_advice', 'MT548cancellation_status_advice'];

        // fetching associated markets
        var user1 = new GlideRecord('sys_user');
        user1.get(gs.getUserID());
        usermarket = user1.u_associated_business_markets;
        //  var split_market = usermarket.split(',');


        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        query ? grTask.addQuery(query) : '';
        grTask.orderBy('bulk_id');
        grTask.query();

        while (grTask.next()) {
            /* MSSCUSTODY-4872 -disabled as per defect.
            //Return false if Task type is not a maker task. 
            if (grTask.trade_task_type != 'Maker' || grTask.active == false || grTask.trade_id.source_system != 'GHSS' || grTask.trade_id.trade_lifecycle_status == 'TradOnHldDueToSnctns' || grTask.trade_case_id.triggered_by.status == 'Trade On-Hold due to Sanctions') {
                enableBulkOption = false;
                break;
            }
            //Return false if bulk id is not null. Bulk operation is applicable for Task not associated with a bulk id
            if (grTask.bulk_id != '') {
                enableBulkOption = false;
                break;
            }
			*/
            //Return false if selected task record does not find matching market.
            if (market.indexOf(grTask.trade_id.owning_business) == -1) {
                enableBulkOption = false;
                break;
            }
            //Return false if selected task record is having multiple Markets.
            if (arrMarket.indexOf(grTask.trade_id.owning_business.toString()) == -1) {
                arrMarket.push(grTask.trade_id.owning_business.toString());
                if (arrMarket.length > 1) {
                    enableBulkOption = false;
                    break;
                }
            }

            //Return false if selected task record is having multiple life cycle status.
            if (arrTradeLifeCycleStatus.indexOf(grTask.trade_id.trade_lifecycle_status.toString()) == -1) {
                arrTradeLifeCycleStatus.push(grTask.trade_id.trade_lifecycle_status.toString());
                if (arrTradeLifeCycleStatus.length > 1) {
                    enableBulkOption = false;
                    break;
                }
            }

            if (usermarket.indexOf(grTask.trade_id.owning_business.toString()) == -1) {
                enableBulkOption = false;
                break;
            }

            // MSSCUSTODY-6379
            if (arrSwiftStatus.includes(grTask.trade_id.trade_lifecycle_status.toString())) {
                if (arrSenderID.indexOf(grTask.trade_id.sender_id.toString()) == -1) {
                    arrSenderID.push(grTask.trade_id.sender_id.toString());
                    if (arrSenderID.length > 1) {
                        enableBulkOption = false;
                        break;
                    }
                }
            }


        }
        return enableBulkOption;

    },


    evalBulkoutcome: function() { //MSSCUSTODY-3543 display outcome on bulk form

        try {

            var bulkID_sysID = this.getParameter('sysparm_sys_id');

            var tradeOwningBusiness = '';
            var amendMarket = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedamend.market');
            var switchLinkMarket = gs.getProperty('x_hsb11_mss_c_proc.enableswitchandlink.market');

            var grbulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            grbulk.get(bulkID_sysID);
            tradeOwningBusiness = grbulk.owning_business.toString();
            grbulk.next();

            var outcomesArray = [];
            var arrConfirmTrade = [];
            var arrPutTradeOnHold = [];
            var arrResumeTrade = [];
            var arrSettleTrade = [];
            var arrProcessTradeCancel = [];
            var arrTradeAmend = [];
            var arrAmendCONF = [];
            var arrConfAndSettTrade = []; //7420
            var pappAppCanc = []; //8274
            var pappAppHold = []; //8274
            var noAmendRequired = []; //8436

            //MSSCUSTODY-7266: 
            if ((grbulk.bulk_type == 'manual_task') && (parseInt(grbulk.active_trade_count) == 1) && (switchLinkMarket.toString().indexOf(tradeOwningBusiness) > -1)) {
                var grSwitchTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                grSwitchTask.addQuery('bulk_id', bulkID_sysID);
                grSwitchTask.addActiveQuery();
                grSwitchTask.addQuery('trade_task_type', 'Maker');
                grSwitchTask.addQuery('trade_id.switch_indicator', 'Y');
                grSwitchTask.addQuery('trade_id.legacy_statusIN PCON,CONF'); //MSSCUSTODY-8195
                grSwitchTask.query();
                if (grSwitchTask.hasNext()) {
                    var switchChoice = {};
                    switchChoice.displayValue = 'Switch Maintenance';
                    switchChoice.value = 'Switch Maintenance';
                    outcomesArray.push(switchChoice);
                }
            }
            // MSSCUSTODY-8274 - PAPP Approval - Hold and Canc
            if ((grbulk.bulk_type == 'manual_task') && (parseInt(grbulk.active_trade_count) == 1) && (amendMarket.toString().indexOf(tradeOwningBusiness) > -1)) {
                // Check for PAPP Approval - Canc
                var grPAPPTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                grPAPPTask.addQuery('bulk_id', bulkID_sysID);
                grPAPPTask.addActiveQuery();
                grPAPPTask.addQuery('trade_task_type', 'Maker');
                grPAPPTask.addQuery('trade_id.legacy_status', 'PAPP');
                grPAPPTask.addQuery('trade_id.legacy_sub_status', 'RCN');
                grPAPPTask.query();
                if (grPAPPTask.hasNext()) {
                    var pappCancChoice = {};
                    pappCancChoice.displayValue = 'PAPP Approval - Canc';
                    pappCancChoice.value = 'PAPP Approval - Canc';
                    outcomesArray.push(pappCancChoice);
                }
                // Check for PAPP Approval - Hold
                var grPAPPHoldTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                grPAPPHoldTask.addQuery('bulk_id', bulkID_sysID);
                grPAPPHoldTask.addActiveQuery();
                grPAPPHoldTask.addQuery('trade_task_type', 'Maker');
                grPAPPHoldTask.addQuery('trade_id.legacy_status', 'PAPP');
                grPAPPHoldTask.addQuery('trade_id.legacy_sub_status', 'RHG');
                grPAPPHoldTask.query();
                if (grPAPPHoldTask.hasNext()) {
                    var pappHoldChoice = {};
                    pappHoldChoice.displayValue = 'PAPP Approval - Hold';
                    pappHoldChoice.value = 'PAPP Approval - Hold';
                    outcomesArray.push(pappHoldChoice);
                }
                // MSSCUSTODY-8436 - Check for No Amend Required
                var noAmendRequired = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                noAmendRequired.addQuery('bulk_id', bulkID_sysID);
                noAmendRequired.addActiveQuery();
                noAmendRequired.addQuery('trade_task_type', 'Maker');
                noAmendRequired.addEncodedQuery('trade_id.trade_lifecycle_status=TradToBeMtchdNtrnly^trade_id.legacy_status=PCON^NQtrade_id.trade_lifecycle_status=TradCaptrdInErr^NQtrade_id.trade_lifecycle_status=TradCaptrdPdgApprvl');
                noAmendRequired.query();
                if (noAmendRequired.hasNext()) {
                    var noAmendReqd = {};
                    noAmendReqd.displayValue = 'No Amendment Required';
                    noAmendReqd.value = 'No Amendment Required';
                    outcomesArray.push(noAmendReqd);
                }
            }

            //MSSCUSTODY-7057
            if ((grbulk.bulk_type == 'manual_task') && (parseInt(grbulk.active_trade_count) == 1) && (switchLinkMarket.toString().indexOf(tradeOwningBusiness) > -1)) {
                var grLinkTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                grLinkTask.addEncodedQuery('bulk_id.sys_idSTARTSWITH' + bulkID_sysID + '^trade_task_type=Maker^trade_id.legacy_status!=^trade_id.legacy_statusINPCON,CONF,CLRG,MTCH^active=true'); // MSSCUSTODY-8436
                grLinkTask.orderByDesc('sys_created_on');
                grLinkTask.setLimit(1);
                grLinkTask.query();
                if (grLinkTask.next()) {
                    var linkChoice = {};
                    linkChoice.displayValue = 'Linking';
                    linkChoice.value = 'Linking';
                    outcomesArray.push(linkChoice);
                }
            }

            if (grbulk.bulk_type == 'manual_task') { // check if the bulk type is manual


                var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); //retrived the bulk record attributes
                grTask.addQuery('bulk_id', bulkID_sysID);
                grTask.addActiveQuery();
                grTask.addQuery('trade_task_type', 'Maker');
                grTask.query();

                while (grTask.next()) {

                    var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                    grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTask.trade_id.owning_business + '^ctac_code=' + grTask.trade_id.trade_lifecycle_status);
                    grBulkEvents.query();
                    if (grBulkEvents.next()) {

                        gs.info('BPS ' + grBulkEvents.sys_id)
                        if (arrConfirmTrade.indexOf(grBulkEvents.confirm_trade.toString()) == -1 && arrConfirmTrade.indexOf('false') == -1) {
                            arrConfirmTrade[0] = grBulkEvents.confirm_trade.toString();
                            arrConfirmTrade[1] = 'Confirm Trade'; // Set outcome display value
                            arrConfirmTrade[2] = 'Confirm Trade'; // Set outcome value
                        }
                        if (arrConfAndSettTrade.indexOf(grBulkEvents.confirm_and_settle_trade.toString()) == -1 && arrConfAndSettTrade.indexOf('false') == -1) { //7420
                            arrConfAndSettTrade[0] = grBulkEvents.confirm_and_settle_trade.toString();
                            arrConfAndSettTrade[1] = 'Confirm and Settle Trade'; // Set outcome display value
                            arrConfAndSettTrade[2] = 'Confirm and Settle Trade'; // Set outcome value
                        }
                        if (arrPutTradeOnHold.indexOf(grBulkEvents.put_trade_on_hold.toString()) == -1 && arrPutTradeOnHold.indexOf('false') == -1) {
                            arrPutTradeOnHold[0] = grBulkEvents.put_trade_on_hold.toString();
                            arrPutTradeOnHold[1] = 'Put Trade On-Hold'; // Set outcome display value
                            arrPutTradeOnHold[2] = 'Put Trade On-Hold'; // Set outcome value
                        }
                        if (arrResumeTrade.indexOf(grBulkEvents.resume_trade.toString()) == -1 && arrResumeTrade.indexOf('false') == -1) {
                            arrResumeTrade[0] = grBulkEvents.resume_trade.toString();
                            arrResumeTrade[1] = 'Resume Trade'; // Set outcome display value
                            arrResumeTrade[2] = 'Resume Trade'; // Set outcome value
                        }
                        if (arrSettleTrade.indexOf(grBulkEvents.settle_trade.toString()) == -1 && arrSettleTrade.indexOf('false') == -1) {
                            arrSettleTrade[0] = grBulkEvents.settle_trade.toString();
                            arrSettleTrade[1] = 'Settle Trade'; // Set outcome display value
                            arrSettleTrade[2] = 'Settle Trade'; // Set outcome value
                        }
                        if (arrProcessTradeCancel.indexOf(grBulkEvents.process_trade_cancellation.toString()) == -1 && arrProcessTradeCancel.indexOf('false') == -1) {
                            arrProcessTradeCancel[0] = grBulkEvents.process_trade_cancellation.toString();
                            arrProcessTradeCancel[1] = 'Process Trade Cancellation'; // Set outcome display value
                            arrProcessTradeCancel[2] = 'Process Trade Cancellation'; // Set outcome value
                        }
                        if (arrTradeAmend.indexOf(grBulkEvents.trade_amend.toString()) == -1 && arrTradeAmend.indexOf('false') == -1 && parseInt(grbulk.active_trade_count) >= 1) { //modified as part of amend to allow only if more than one trade // MSSCUSTODY-8436
                            arrTradeAmend[0] = grBulkEvents.trade_amend.toString();
                            arrTradeAmend[1] = 'Amend Trade'; // Set outcome display value
                            arrTradeAmend[2] = 'Amend Trade'; // Set outcome value
                        }
                        if (arrAmendCONF.indexOf(grBulkEvents.amend_and_conf.toString()) == -1 && arrAmendCONF.indexOf('false') == -1 && parseInt(grbulk.active_trade_count) >= 1) { //allow only if more than one trade // MSSCUSTODY-8436
                            arrAmendCONF[0] = grBulkEvents.amend_and_conf.toString();
                            arrAmendCONF[1] = 'Amend and CONF'; // Set outcome display value
                            arrAmendCONF[2] = 'Amend and CONF'; // Set outcome value
                        }
                        // MSSCUSTODY-8274
                        if (pappAppHold.indexOf(grBulkEvents.papp_approval_hold.toString()) == -1 && pappAppHold.indexOf('false') == -1 && parseInt(grbulk.active_trade_count) > 1) { // MSSCUSTODY 8274 - allow only if more than one trade
                            pappAppHold[0] = grBulkEvents.papp_approval_hold.toString();
                            pappAppHold[1] = 'PAPP Approval - Hold'; // Set outcome display value
                            pappAppHold[2] = 'PAPP Approval - Hold'; // Set outcome value
                        }
                        // MSSCUSTODY-8274
                        if (pappAppCanc.indexOf(grBulkEvents.papp_approval_canc.toString()) == -1 && pappAppCanc.indexOf('false') == -1 && parseInt(grbulk.active_trade_count) > 1) { // MSSCUSTODY 8274 - allow only if more than one trade
                            pappAppCanc[0] = grBulkEvents.papp_approval_canc.toString();
                            pappAppCanc[1] = 'PAPP Approval - Canc'; // Set outcome display value
                            pappAppCanc[2] = 'PAPP Approval - Canc'; // Set outcome value
                        }
                        // MSSCUSTODY-8136
                        if (noAmendRequired.toString().indexOf(grBulkEvents.no_amendment_required.toString()) == -1 && noAmendRequired.toString().indexOf('false') == -1) { // MSSCUSTODY 8136 - allow only if more than one trade

                            gs.info('no amend loop')
                            noAmendRequired[0] = grBulkEvents.no_amendment_required.toString();
                            noAmendRequired[1] = 'No Amendment Required'; // Set outcome display value
                            noAmendRequired[2] = 'No Amendment Required'; // Set outcome value
                        }
                    }
                }
                var outcomesArrayTemp = [];
                outcomesArrayTemp.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend, arrAmendCONF, arrConfAndSettTrade, pappAppHold, pappAppCanc, noAmendRequired); //pushed all the outcome values in temp array     //7420 // MSSCUSTODY-8274 // MSSCUSTODY-8136

                for (i = 0; i < outcomesArrayTemp.length; i++) { //create outcome choices
                    if (outcomesArrayTemp[i][0] == 'true') { //check for true values
                        var manualTaskChoice = {};
                        manualTaskChoice.displayValue = outcomesArrayTemp[i][1]; //store outcome display value
                        manualTaskChoice.value = outcomesArrayTemp[i][2]; // store outcome value
                        outcomesArray.push(manualTaskChoice); //pushed all the display value and value in main array
                    }
                }

            }

            if (grbulk.bulk_type == 'automated_task') { // check if the bulk type is automated

                var grTask2 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); //retrived the bulk record attributes
                grTask2.addQuery('bulk_id', bulkID_sysID);
                grTask2.addActiveQuery();
                grTask2.addQuery('trade_task_type', 'Maker');
                grTask2.query();
                if (grTask2.next()) {
                    var grOutcomeMapping = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping'); //check for the matching record in task outcome mapping table
                    grOutcomeMapping.addQuery('trade_template_id', grbulk.trade_task_template_id);
                    grOutcomeMapping.addEncodedQuery('marketLIKE' + grbulk.owning_business);
                    grOutcomeMapping.query();
                    while (grOutcomeMapping.next()) {
                        var automatedTaskChoice = {};
                        automatedTaskChoice.displayValue = grOutcomeMapping.getDisplayValue('outcome'); //store outcome display value
                        automatedTaskChoice.value = grOutcomeMapping.getValue('outcome'); // store outcome value
                        outcomesArray.push(automatedTaskChoice); //pushed all the display value and value in main array
                    }
                }
            }
            //MSSCUSTODY-3456 add review and closed the task outcome option if maker task is created from checker rejection
            //gs.info('Checking for bulk_id: ' + bulkID_sysID);
            var grCustodyTask = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            grCustodyTask.addEncodedQuery("sub_trade_task_typeINChecker-Rejected,Automation Failed^state=2^ORstate=1^trade_task_type=Maker^bulk_id=" + bulkID_sysID);
            grCustodyTask.query();
            if (grCustodyTask.next()) {
                //gs.info('Found custody task sys_id: ' + grCustodyTask.getValue('sys_id') + ', sub_trade_task_type: ' + grCustodyTask.getValue('sub_trade_task_type') + ', state: ' + grCustodyTask.getValue('state'));
                var reviewClosedTaskChoice = {};
                reviewClosedTaskChoice.displayValue = 'Review and closed the task'; //store outcome display value
                reviewClosedTaskChoice.value = 'Review and closed the task'; // store outcome value
                outcomesArray.push(reviewClosedTaskChoice);
                //gs.info('Added outcome.');
            }

            gs.info("returned Outcomes " + JSON.stringify(outcomesArray));

            return JSON.stringify(outcomesArray);

        } catch (ex) {
            gs.info('Error From x_hsb11_mss_c_proc.MSSCustodyBulkUtils- evalBulkOutcome : ' + ex);
        }
    },

    //-------------------------Switch & Link------------------------------------

    //MSSCUSTODY-7266
    getSwitchSuboutcome: function() {
        try {
            var bulkID_sysID = this.getParameter('sysparm_sys_id');
            var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            grTask.addQuery('bulk_id', bulkID_sysID);
            grTask.addActiveQuery();
            grTask.addQuery('trade_task_type', 'Maker');
            grTask.orderBy('sys_created_on');
            grTask.query();

            var hasSwitchReference = false;
            var legacyStatus = '';
            while (grTask.next()) {
                if (grTask.trade_id.switch_reference) {
                    hasSwitchReference = true;
                    //break;
                }
                legacyStatus = grTask.trade_id.legacy_status + '';
                break;
            }

            var suboutcomes = [];
            if (hasSwitchReference && (legacyStatus === 'PCON' || legacyStatus === 'CONF')) {
                suboutcomes.push({
                    value: 'De-Pair Trade',
                    displayValue: 'De-Pair Trade'
                });
            }
            if (!hasSwitchReference && (legacyStatus === 'PCON' || legacyStatus === 'CONF')) { // MSSCUSTODY-8424 - Added CONF legacy status
                suboutcomes.push({
                    value: 'Convert to Non-Switching Trade',
                    displayValue: 'Convert to Non-Switching Trade'
                });
            }
            if (!hasSwitchReference && (legacyStatus === 'PCON' || legacyStatus === 'CONF')) { // MSSCUSTODY-8033 - Added condition for Pair trade
                suboutcomes.push({
                    value: 'Pair Trade',
                    displayValue: 'Pair Trade'
                });
            }
            return JSON.stringify(suboutcomes);
        } catch (e) {
            gs.error('Error in Script Include MSSCustodyBulkUtils, getSwitchSuboutcome: ' + e.message);
        }
    },

    //MSSCUSTODY-7266
    getTradeDetailsForSwitch: function() {
        try {
            var bulkID_sysID = this.getParameter('sysparm_sys_id');
            var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            grTask.addQuery('bulk_id', bulkID_sysID);
            grTask.addActiveQuery();
            grTask.addQuery('trade_task_type', 'Maker');
            grTask.orderBy('sys_created_on');
            grTask.query();

            if (grTask.next()) {
                var tradeID = grTask.getValue('trade_id');
                if (tradeID) {
                    var tradeGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (tradeGr.get(tradeID)) {
                        var result = {
                            'tradeLegStatus': tradeGr.getValue('legacy_status'),
                            'tradeLocCode': tradeGr.getValue('location_code'),
                            'tradeScripHold': tradeGr.getValue('security_id'),
                            'tradeSecAccnt': tradeGr.getValue('securities_account'),
                            'tradeSettAmt': tradeGr.getValue('settlement_amount'),
                            'tradeSettDate': tradeGr.getValue('settlement_date'),
                            'tradeSwitchAccnt': tradeGr.getValue('switch_account'),
                            'tradeQuantity': tradeGr.getValue('settlement_quantity'),
                            'tradeTransType': tradeGr.getValue('transaction_type'),
                            'tradeTransRef': tradeGr.getValue('transaction_reference')
                        };
                        return JSON.stringify(result);
                    }
                }
            }

        } catch (e) {
            gs.error('Error in Script Include MSSCustodyBulkUtils, getTradeDetailsForSwitch: ' + e.message);
        }
    },

    //MSSCUSTODY-7266
    getSwitchReferenceValue: function() {
        try {
            var bulkID_sysID = this.getParameter('sysparm_sys_id');
            var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            grTask.addQuery('bulk_id', bulkID_sysID);
            grTask.addActiveQuery();
            grTask.addQuery('trade_task_type', 'Maker');
            grTask.query();

            if (grTask.next()) {
                var tradeID = grTask.getValue('trade_id');
                if (tradeID) {
                    var tradeGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (tradeGr.get(tradeID)) {
                        result = tradeGr.getValue('switch_reference');
                        //return JSON.stringify(result);
                        return result;
                    }
                }
