    //Linking
    //MSSCUSTODY-7057
    getLinkSuboutcome: function() {
        try {
            var bulkID_sysID = this.getParameter('sysparm_sys_id');
            var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            grTask.addQuery('bulk_id', bulkID_sysID);
            //grTask.addActiveQuery();
            grTask.addQuery('trade_task_type', 'Maker');
            grTask.orderBy('sys_created_on');
            grTask.query();

            var hasLinkReference = false;
            var legacyStatus = '';
            var linkIndicator = '';
            while (grTask.next()) {
                if (grTask.trade_id.link_reference) {
                    hasLinkReference = true;
                }
                linkIndicator = grTask.trade_id.link_indicator;
                legacyStatus = grTask.trade_id.legacy_status + '';
                break;
            }

            var suboutcomes = [];

            if (!hasLinkReference && ['PCON', 'CONF', 'CLRG', 'MTCH'].includes(legacyStatus)) {
                suboutcomes.push({
                    value: 'Link Trade',
                    displayValue: 'Link Trade'
                });
            }

            if (hasLinkReference && linkIndicator == 'Y' && ['PCON', 'CONF', 'CLRG', 'MTCH'].includes(legacyStatus)) {
                suboutcomes.push({
                    value: 'De-Link Trades',
                    displayValue: 'De-Link Trades'
                });
            }

            if (!hasLinkReference && linkIndicator == 'Y' && ['PCON', 'CONF', 'CLRG', 'MTCH'].includes(legacyStatus)) {
                suboutcomes.push({
                    value: 'Self De-Link Trade',
                    displayValue: 'Self De-Link Trade'
                });
            }

            return JSON.stringify(suboutcomes);
        } catch (e) {
            gs.error('Error in Script Include MSSCustodyBulkUtils, getLinkSuboutcome: ' + e.message);
        }
    },

    //MSSCUSTODY-7057
    getLinkTrade: function(bulkSysId) {
        try {
            var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            grTask.addQuery('bulk_id', bulkSysId);
            //grTask.addActiveQuery();
            grTask.addQuery('trade_task_type', 'Maker');
            grTask.orderBy('sys_created_on');
            grTask.query();

            var tradeDate = null;
            var settDate = null;
            var transType = '';
            var secAccnt = '';
            var settQuan = 0.0;
            var secId = '';

            if (grTask.next()) {
                tradeDate = grTask.trade_id.trade_date;
                settDate = grTask.trade_id.settlement_date;
                transType = grTask.trade_id.transaction_type;
                secAccnt = grTask.trade_id.securities_account;
                settQuan = grTask.trade_id.settlement_quantity;
                secId = grTask.trade_id.security_id;
            }

            var trades = [];
            var tradeGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            tradeGr.addEncodedQuery("link_referenceISEMPTY^legacy_statusINPCON,CONF,CLRG,MTCH");
            if (tradeDate) {
                tradeGr.addQuery('trade_date', tradeDate);
            }
            tradeGr.addQuery('settlement_date', settDate);
            tradeGr.addQuery('securities_account', secAccnt);
            tradeGr.addQuery('settlement_quantity', settQuan);
            tradeGr.addQuery('security_id', secId);
            /*if (transType == 'RVP') {
                tradeGr.addQuery('transaction_type', 'DVP');
            } else if (transType == 'DVP') {
                tradeGr.addQuery('transaction_type', 'RVP');
            } else if (transType == 'RFP') {
                tradeGr.addQuery('transaction_type', 'DFP');
            } else if (transType == 'DFP') {
                tradeGr.addQuery('transaction_type', 'RFP');
            }*/ // Commneted as part of MSSCUSTODY-8697

            // MSSCUSTODY 8697 - Transaction type pairing
            var pairingMap = {
                'RVP': ['DVP', 'DFP'],
                'RFP': ['DFP', 'DVP'],
                'DVP': ['RVP', 'RFP'],
                'DFP': ['RFP', 'RVP']
            };
			if (pairingMap[transType]) {
                tradeGr.addQuery('transaction_type', pairingMap[transType]);
            }

            tradeGr.query();
            while (tradeGr.next()) {
                trades.push(tradeGr.sys_id.toString());
            }
