    getTradeDetailsDeLink: function() { //MSSCUSTODY-8162
        try {
            var bulkId = this.getParameter('sysparm_bulk_id');
            var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskGR.addEncodedQuery('bulk_id=' + bulkId + '^trade_task_type=Maker');
            taskGR.query();
            if (taskGR.next()) {
                var tradeId = taskGR.trade_id.sys_id;
                if (!tradeId) return '';
                var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                if (tradeGR.get(tradeId)) {
                    var linkRef = tradeGR.link_reference ? tradeGR.link_reference.toString() : '';
                    if (!linkRef) return '';
                    var otherTradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    otherTradeGR.addEncodedQuery('link_reference=' + linkRef + '^sys_id!=' + tradeId);
                    otherTradeGR.query();
                    if (otherTradeGR.next()) {
                        var result = {
                            link_reference: otherTradeGR.link_reference ? otherTradeGR.link_reference.toString() : '',
                            transaction_reference: otherTradeGR.transaction_reference ? otherTradeGR.transaction_reference.toString() : '',
                            transaction_type: otherTradeGR.transaction_type ? otherTradeGR.transaction_type.toString() : '',
                            settlement_quantity: otherTradeGR.settlement_quantity ? otherTradeGR.settlement_quantity.toString() : '',
                            legacy_status: otherTradeGR.legacy_status ? otherTradeGR.legacy_status.toString() : '',
                            hold_indicator: otherTradeGR.script_hold_indicator ? otherTradeGR.script_hold_indicator.toString() : ''
                        };
                        gs.info('de link: ' + JSON.stringify(result));
                        return JSON.stringify(result);
                    }
                }
            }
            return '';
        } catch (e) {
            gs.info('error in get details for de link trade: ' + e.message);
        }
    },
