    //MSSCUSTODY-7706
    decrementTradeCount: function(bulkId) {
        var MAX_RETRIES = 7;
        var RETRY_DELAY_MS = 500; // milliseconds
        var attempt = 0;

        function sleep(ms) {
            var start = new Date().getTime();
            while (new Date().getTime() < start + ms) {}
        }

        if (bulkId && bulkId != '') {
            while (attempt < MAX_RETRIES) {
                var grBulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
                if (grBulk.get(bulkId)) {
                    if (!grBulk.race_lock) {
                        grBulk.race_lock = true;
                        grBulk.update();

                        grBulk.active_trade_count--;
                        grBulk.race_lock = false;
                        grBulk.update();
                        gs.info('active_trade_count upadated for bulk:' + bulkId);
                        return;
                    }
                    sleep(RETRY_DELAY_MS);
                    attempt++;
                } else {
                    return;
                }
            }
            gs.info('Failed to acquire lock after max retries. Skipping decrement.');
        }
    },


    createAutomatedTaskBulkID: function() { //MSSCUSTODY-3495, MSSOTIQUBE-2183

        //Create bulk id from Task list and map same bulk id to MSS Custody Case and MSS Custody Task.

        var query = this.getParameter('sysparm_query');
        //gs.debug("Query details : "+query);
        //gs.info('Query Details from info ' + query);
        var count = this.getParameter("sysparm_taskcount"); //MSSCUSOTDY- 4282
        var makerAssignmentGroup = this.getAssignmentGroup('x_hsb11_mss_custod.custody_maker');
        var filter = this.getParameter('sysparm_filter'); //MSSCUSTODY-6655

        var grbulkId = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        grbulkId.initialize();
        // grbulkId.assignment_group = makerAssignmentGroup;
        // grbulkId.assigned_to = gs.getUserID();
        grbulkId.state = 2;
        //grbulkId.lock = true; // MSSCUSTODY-3992


        var bulkTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00112')); //Template selection
        grbulkId.short_description = bulkTemplate.shortDescription; //deparsed from method selectTaskTemplate
        grbulkId.description = bulkTemplate.description; //deparsed from method selectTaskTemplate
        grbulkId.applied_filter = filter || ''; // MSSCUSTODY-6655
        grbulkId.bulk_task_type = 'Maker';
        grbulkId.bulk_type = 'automated_task';
        grbulkId.active_trade_count = count; //MSSCUSTODY-4282
        grbulkId.insert();

        var grtask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        grtask.addQuery(query);
        grtask.setValue('bulk_id', grbulkId.sys_id);
        //grtask.setValue('assignment_group', makerAssignmentGroup);
        //grtask.setValue('assigned_to', gs.getUserID());
        grtask.setValue('lock', true);
        grtask.setValue('locktime', new GlideDateTime());
        grtask.setWorkflow(false);
        grtask.updateMultiple();

        //Fetch Task ids from Task table to store in array
        var case_array = [];
        var owningbusiness;
        var tasktemplateid;
        var tasksys = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        //tasksys.addQuery(query);
        tasksys.addQuery('bulk_id', "=", grbulkId.sys_id);
        tasksys.query();
        while (tasksys.next()) {
            case_array.push(tasksys.trade_case_id.toString());
            owningbusiness = tasksys.trade_id.owning_business;
            tasktemplateid = tasksys.trade_task_template_id;
            //gs.info('Task Array value is ', case_array.length);
        }

        //Update Case with Bulk Id using array
        if (case_array.length != 0) {
            var grcase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
            grcase.addEncodedQuery('sys_idIN' + case_array + '^bulk_idISEMPTY');
            grcase.setValue('bulk_id', grbulkId.sys_id);
            grcase.setWorkflow(false);
            grcase.updateMultiple();
        }


        if (grbulkId.get(grbulkId.sys_id)) {
            grbulkId.owning_business = owningbusiness;
            // gs.info('ob-bulk' + grbulkId.owning_business);
            grbulkId.trade_task_template_id = tasktemplateid;
            // gs.info('ttt-bulk' + grbulkId.trade_task_template_id);
            grbulkId.update();
        }
        return grbulkId.sys_id;
    },

    evalBulkOptionSingleTrade: function(trdID) {
        //Created as part of UI action Manual Maintenance for MSSCUSTODY- 3610
        /* This method is utlilized to check the following 
        1) If 'confirm_trade'or 'put_trade_on_hold'or 'resume_trade'or 'settle_trade or process_trade_cancellation'or 'trade_amend' 
        in th Business Process Stages table returns "true" for the respective Owning Business in the trade
        2) IF the trade Case Type = No Open Case
        3) If the trade Life Cycle status is not one of Trade Settled or Trade Cancelled
        4) If the logged in user holds x_hsb11_mss_custod.custody_maker role
        Currently called in UI Action : Trigger Manual Case */
        try {
            var enabmarket = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');
            var allowedSourceSystem = gs.getProperty('x_hsb11_mss_c_proc.triggerManualCaseAllowedSourceSystem');

            // fetching associated markets
            var user1 = new GlideRecord('sys_user');
            user1.get(gs.getUserID());
            usermarket = user1.u_associated_business_markets;

            var grTrade = new GlideRecordSecure('x_hsb11_mss_c_proc_mss_custody_trade');
            if (grTrade.get(trdID)) {

                //check if there are any active cases
                var cseType = 'no_open_case';
                var getCaseDetails = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                getCaseDetails.addEncodedQuery('trade_id.sys_idSTARTSWITH' + grTrade.sys_id + '^active=true');
                getCaseDetails.orderByDesc('sys_created_on');
                getCaseDetails.query();
                if (getCaseDetails.next()) {
                    cseType = 'open_case';

                }
                //check if there are any active cases


                var market = grTrade.owning_business.toString(); //owning business
                //var cseType = grTrade.getValue('case_type'); // Trade Case Type
                var trdLifeCycle = grTrade.getValue('trade_lifecycle_status'); // Trade Life Cycyle Status
                var trdSource = grTrade.getValue('source_system'); // Trade Source System
                var bpiStage = new GlideRecordSecure('x_hsb11_hsbc_mss_o_business_process_stage'); //evaluate if any of the value in BPI table is valid for the respective market
                bpiStage.addEncodedQuery('business_process.process_name=Trade Lifecycle Status' + '^ctac_code=' + trdLifeCycle + '^market=' + market); //Evaluating the Business Process Stage table for any value true in the array declared below
                bpiStage.query();
                if (bpiStage.next()) {
                    var trdChk = ['confirm_trade', 'put_trade_on_hold', 'resume_trade', 'settle_trade', 'process_trade_cancellation', 'trade_amend', 'papp_approval_hold', 'papp_approval_canc']; // MSSCUSTODY-8274
                    var flag = false;

                    for (var i = 0; i < trdChk.length; i++) {

                        if (bpiStage.getValue(trdChk[i]) == true) {
                            flag = true;
                            break; //exit loop if any of the value returns true from BPI table
                        } else
                            flag = false;
                    }
                    if (flag) { //return true if anyone value of the array in business process stage table is declared as true.

                        if ((enabmarket.indexOf(market) > -1) && (usermarket.indexOf(market) > -1) && (cseType == 'no_open_case') && (trdLifeCycle != 'TradCanc') && (trdLifeCycle != 'TradSttld') && (allowedSourceSystem.indexOf(trdSource) > -1) && (gs.hasRole('x_hsb11_mss_custod.custody_maker')) && (!gs.hasRole('x_hsb11_mss_custod.custody_checker') || gs.hasRole('admin'))) {

                            return true; //if there are no active cases,trade Life cycle is not Trade Settled or trade Cancelled,the Source system is GHSS and the logged in user holds Custody maker role
                        } else {
                            return false;
                        }

                    } else {
                        return false; //return false if every value of the array in business process stage table is declared as false
                    }
                } else {
                    return false; // if no records found in BPI table
                }


            }
        } catch (ex) {
            var message = ex.message;
            gs.info("Error from script Include MSSCustodyBulkUtils - evalBulkOptionSingleTrade: " + message);
        }
    }, //Created as part of UI action Manual Maintenance for MSSCUSTODY-3610

    evalTradeAmend: function(trdID) {
        //Created as part of UI action Manual Maintenance for MSSCUSTODY- 3610
        /* This method is utlilized to check the following 
        1) If 'confirm_trade'or 'put_trade_on_hold'or 'resume_trade'or 'settle_trade or process_trade_cancellation'or 'trade_amend' 
        in th Business Process Stages table returns "true" for the respective Owning Business in the trade
        2) IF the trade Case Type = No Open Case
        3) If the trade Life Cycle status is not one of Trade Settled or Trade Cancelled
        4) If the logged in user holds x_hsb11_mss_custod.custody_maker role
        Currently called in UI Action : Trigger Amend */
        try {
