    //MSSCustody3417 get count of checker tasks based on sub trade task type field
    getCheckerTaskCount: function() {

        var bulkid = this.getParameter('sysparm_bulkid');
        var chkObj = {};
        var checkerCount = 0;
        var checkerRejectCount = 0;
        var gaTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        gaTask.addEncodedQuery('active=true^trade_task_type=Checker^sub_trade_task_type=Checker^ORsub_trade_task_type=Checker-To be Rejected^bulk_id=' + bulkid);
        gaTask.query();
        while (gaTask.next()) {
            if (gaTask.sub_trade_task_type == 'Checker') {
                checkerCount++;
                chkObj.chkCount = checkerCount;
            }
            if (gaTask.sub_trade_task_type == 'Checker-To be Rejected') {
                checkerRejectCount++;
                chkObj.chkRejCount = checkerRejectCount;
            }
        }
        return (JSON.stringify(chkObj));
    },

