    updateMakerTask: function() { //MSSCUSTODY-3396

        var bulkid = this.getParameter('sysparm_bulkid');
        var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
        var assignedto = this.getParameter('sysparm_assignedto');
        var outcome = this.getParameter('sysparm_outcome');
        var advice = this.getParameter('sysparm_advice');
        var reasoncode = this.getParameter('sysparm_reasoncode');
        var reasondesc = this.getParameter('sysparm_reasondescription');
        var suspend = this.getParameter('sysparm_suspend');
        var cancelby = this.getParameter('sysparm_cancelby');
        var setttype = this.getParameter('sysparm_settlementtype');
        var bktobkinfo = this.getParameter('sysparm_bktobk');
        var cancreference = this.getParameter('sysparm_cancellationreference');
        var cancelcharge = this.getParameter('sysparm_collectcancelcharge');
        //adding as part of 4901
        var settDate = this.getParameter('sysparm_settDate');
        var fxrTD = this.getParameter('sysparm_fxrTD');
        var valDate = this.getParameter('sysparm_valDate');

        //MSSCUSTODY-6087
        var fxcx = this.getParameter('sysparm_fxcx');
        var gdi = this.getParameter('sysparm_gdi');

        // MSSCUSTODY-6379
        var comments = this.getParameter('sysparm_comments');

        // MSSCUSTODY-6821 // 7191
        var uploadType = this.getParameter('sysparm_uploadType');
        var expectedTaskCount = this.getParameter('sysparm_tasksCount');
        var updatedTaskCount = 0;

        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        grTask.addEncodedQuery('active=true^trade_task_type=Maker^bulk_id=' + bulkid);
        grTask.query();
        while (grTask.next()) {
            if (outcome == 'Review and closed the task') { // MSSCUSTODY-3964 - Cancelling associated flow if outcome is review and close the task for manual.
                grTask.state = '3'; //closing related maker task
                grTask.assignment_group = assignmentgroup; //Populating assignment group
                grTask.assigned_to = assignedto; //Populating assigned to
                grTask.outcome = outcome;
                grTask.lock = false; //MSSCUSTODY-3993
                grTask.update();
                var grCusCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                grCusCase.addEncodedQuery('sys_id=' + grTask.trade_case_id + '^bulk_id=' + bulkid);
                grCusCase.query();
                if (grCusCase.next()) {
                    grCusCase.state = '3';
                    grCusCase.update();

                }

                new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().cancelFlow(grTask.trade_case_id, 'Cancelling flow as state is Review and Close');
                grTask.work_notes = 'Cancelling flow as state is Review and Close'; // Updating work notes of Task
            } else {
                grTask.assignment_group = assignmentgroup; //Populating assignment group
                grTask.assigned_to = assignedto; //Populating assigned to
                grTask.outcome = outcome;
                grTask.advice = advice;
                if ((uploadType == '') || (uploadType == 'bulk_level')) {
                    grTask.reason_code = reasoncode;
                    grTask.reason_description = reasondesc;
                    grTask.cancellation_reference = cancreference;
                }
                grTask.suspend = suspend;
                grTask.cancel_by = cancelby; // for outcome 'Process Trade Cancellation'
                grTask.settlement_type = setttype; // for outcome 'Settle Trade'
                grTask.bk_to_bk_info = bktobkinfo;
                grTask.collect_cancel_charge = cancelcharge;
                grTask.state = '3'; //closing related maker task
                grTask.lock = false; //MSSCUSTODY-3993

                // MSSCUSTODY-6379
                grTask.work_notes = comments;

                //MSSCUSTODY-6087
                grTask.fx_cx = fxcx;
                gtTask.gdi_indicator = gdi;

                //added as part of 4901
                if ((grTask.trade_id.contract_type == 'C') && (outcome == 'Confirm Trade')) {
                    grTask.value_date = valDate;
                } else if ((grTask.trade_id.contract_type != 'C') && (outcome == 'Confirm Trade')) {
                    grTask.value_date = "";
                } else if ((grTask.trade_id.contract_type == 'A') && (outcome == 'Settle Trade')) {
                    grTask.value_date = valDate;
                } else if ((grTask.trade_id.contract_type != 'A') && (outcome == 'Settle Trade')) {
                    grTask.value_date = "";
                } else if (((grTask.trade_id.fx_location == 'L') || (grTask.trade_id.fx_location == 'O')) && (outcome == 'Process Trade Cancellation')) {
                    grTask.fxr_td = fxrTD;
                } else if ((grTask.trade_id.fx_location != 'L') && (grTask.trade_id.fx_location != 'O') && (outcome == 'Process Trade Cancellation')) {
                    grTask.fxr_td = "";
                }
                grTask.settlement_date = settDate;
                grTask.update();

            }
            updatedTaskCount++;
        }
        gs.info('7111: ' + updatedTaskCount);

        if (expectedTaskCount == updatedTaskCount) {
            var bulkgr = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction"); {
                if (bulkgr.get(bulkid)) {
                    bulkgr.bulk_status = 'Ready for Checker';
                    bulkgr.update();
                }
            }

        }


        var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
        grbulk.addQuery("sys_id", bulkid);
        grbulk.query();
        if (grbulk.next()) {
            if (grbulk.outcome == 'Review and closed the task') {
                grbulk.bulk_task_type = 'GHSS Handler';
            } else {
                grbulk.bulk_task_type = 'Checker';
            }
            grbulk.current_maker_assignee = assignedto;
            grbulk.maker_assignment_group = assignmentgroup;
            grbulk.new_maker_task_assignee = assignedto;
            grbulk.outcome = outcome;
            grbulk.advice = advice;
            grbulk.reason_code = reasoncode;
            grbulk.reason_description = reasondesc;
            grbulk.suspend = suspend;
            grbulk.cancel_by = cancelby;
            grbulk.settlement_type = setttype;
            grbulk.bk_to_bk_info = bktobkinfo;
            grbulk.cancellation_reference = cancreference;
            grbulk.collect_cancel_charge = cancelcharge;
            grbulk.assigned_to = '';
            grbulk.lock = false; //MSSCUSTODY-3993
            //adding as part of 4901
            grbulk.settlement_date = settDate;
            grbulk.fxr_td = fxrTD;
            grbulk.value_date = valDate;

            //MSSCUSTODY-6087
            grbulk.fx_cx = fxcx;
            grbulk.gdi = gdi;

            // MSSCUSTODY-6379
            grbulk.comments = comments;

            grbulk.update();
        }
        return true;

    },

