  updateCheckerTask: function() {

        var bulkid = this.getParameter('sysparm_bulkid');
        var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
        var assignedto = this.getParameter('sysparm_assignedto');
        var decision_reason = this.getParameter('sysparm_decision_reason');
        var makerAssignmentgroup = this.getParameter('sysparm_makerAssignmentgroup');
        var reasondescription = this.getParameter('sysparm_reasondescription');
        var newMakerasignee = this.getParameter('sysparm_newMakerasignee');
        var comments = this.getParameter('sysparm_comments');
        var rejecttaskflag = this.getParameter('sysparm_rejecttaskflag');
        var decision = this.getParameter('sysparm_decision');
        var outcome = this.getParameter('sysparm_outcome');


        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        grTask.addEncodedQuery('active=true^trade_task_type=Checker^sub_trade_task_type=Checker^ORsub_trade_task_type=Checker-To be Rejected^bulk_id=' + bulkid);
        grTask.query();
        while (grTask.next()) {
            if (outcome != 'Amend Trade' || grTask.amend_checker_decision == 'Amend') {
                if (grTask.sub_trade_task_type == 'Checker') {
                    grTask.decision = 'approve';
                }
            } else if (outcome == 'Amend Trade' && grTask.amend_checker_decision == 'Amend_Recreated') {
                if (decision == 'approve') {
                    grTask.decision = 'approve';
                } else if (decision == 'manually_close') {
                    grTask.decision = 'manually_close';
                }else if (decision == 'reject_ghss_bulk'){
					grTask.decision = 'reject_ghss';
				}
            }
            if (grTask.sub_trade_task_type == 'Checker-To be Rejected') {
                grTask.decision = 'Reject and create a new task';
                grTask.setValue('sub_trade_task_type', 'Checker-Rejected');
                grTask.decision_reason = decision_reason;
                grTask.work_notes = comments;
                grTask.maker_assignment_group = makerAssignmentgroup;
                grTask.new_maker_task_assignee = newMakerasignee;
            }
            grTask.lock = false;
            grTask.assigned_to = assignedto;
            grTask.assignment_group = assignmentgroup;
            grTask.state = '3'; //set state as closed complete
            grTask.update();
        }

        var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
        grbulk.addQuery("sys_id", bulkid);
        grbulk.query();
        if (grbulk.next()) {

            if (rejecttaskflag == 'false') {
                grbulk.bulk_task_type = 'GHSS Handler';
            }
            grbulk.decision_reason = decision_reason;
            grbulk.maker_assignment_group = makerAssignmentgroup;
            grbulk.new_maker_task_assignee = newMakerasignee;
            grbulk.comments = comments;
            grbulk.update();

        }
        return true;
    },


    //MSSCUSTODY - 3658 Checker Task Verification
    //Modified as part of MSSCUSTODY-6691
    bulkCheckerTaskVerification: function(bulkID, userID) {

        /*The method checks for all the ineligible trades which holds high Nominal Settlement /Settlement amount in USD 
         with respect to the current assigned Checker's allowed band limit USD and the decision matrix is populated
         Based on the decision matrix[false, true....] the trdApprEligibility will be set to false or true which is utilized in the 
         Business rule - Validate Band Limit for Checker - Bulk
         */
        var trades = []; //fetching all the checker task with confirm or settle trade
        var highValTrades = []; //Ineligible Trades
        var decMatrix = []; //holds true or false for approver eligibility
        var trdApprEligibility = ''; //true or false based on the decMatrix
        var embeddedLink = ''; //Clickable link for the trade ID

        //fetching all the checker task with confirm or settle trade
        var bul = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        bul.addEncodedQuery('active=true^trade_task_type=Checker^sub_trade_task_type=Checker^bulk_id.sys_idSTARTSWITH' + bulkID);
        bul.query();
        while (bul.next()) {
            trades.push(bul.trade_id + '');
        }

        if (trades.length > 0) { //added as part if  defect MSSCUSTODY-4172 to validate if there are any tasks as per the query
            var bandLimit = new checkBandLimit();
            for (var i = 0; i < trades.length; i++) {
                var result = bandLimit.isTradeAboveBandLimit(trades[i], userID);
                if (result.aboveLimit) {
                    var grTrade = result.trade;
                    embeddedLink = "<a href='/nav_to.do?uri=x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=" + grTrade.sys_id + "' target='_blank'><strong>" + grTrade.trade_id + "</strong></a>";
                    highValTrades.push(embeddedLink + " |" + '');
                    decMatrix.push('false');
                }
            }

            //Populate the decision matrix with 'false' if any of the trades are noteligible
            if (decMatrix.indexOf('false') > -1) {
                trdApprEligibility = 'false';
            }

            var tradeApprovalCheck = {
                "tradeEligibility": trdApprEligibility,
                "highValTrades": highValTrades.toString()
            };

            return JSON.stringify(tradeApprovalCheck);
        }
    },
    //MSSCUSTODY - 3658 Checker Task Verification


    //MSSCUSTODY - 3415 Bulk Operations - Checker Verification and Approval/ Rejection- Bulk checker form

    RemoveMakerTask: function() { //MSSCUSTODY-3546

        //MSSOTIQUBE-2350
        try {
            var bulkID = this.getParameter('sysparm_bulkID'); //get the passed bulk_id
            var taskID = this.getParameter('sysparm_taskID'); //get the passed array of sys_ids

            //MSSOTIQUBE-2350 
            if (!taskID) {
                return;
            }

            var manualTaskIds = []; // To store sys_ids of manual tasks
            var automatedTaskIds = []; // To store sys_ids of automated tasks
            var manualCaseIds = []; // To store case IDs for manual tasks
            var automatedCaseIds = []; // To store case IDs for automated tasks

            var gCustody = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); // Common GlideRecord object
            gCustody.addEncodedQuery('sys_idIN' + taskID); // Query tasks with the provided sys_ids
            gCustody.query();

            while (gCustody.next()) {
                var caseType = gCustody.trade_id.case_type; // Fetch the case type directly
                var taskSysID = gCustody.getValue('sys_id'); // Get custody task sys_ids
                if (caseType == 'manual') {
                    manualTaskIds.push(taskSysID); // Collect manual task sys_ids
                    var tradeCaseId = gCustody.getValue('trade_case_id'); // Fetch trade_case_id
                    if (tradeCaseId)
                        manualCaseIds.push(tradeCaseId); // Add to manual case IDs
                } else if (caseType == 'automated') {
                    automatedTaskIds.push(taskSysID); // Collect automated task sys_ids
                    var tradeCaseId = gCustody.getValue('trade_case_id'); // Fetch trade_case_id
                    if (tradeCaseId)
                        automatedCaseIds.push(tradeCaseId); // Add to automated case IDs
                }
            }
            // ------Process Manual tasks in bulk------
            if (manualTaskIds.length > 0) {
                gCustody.initialize(); // Reuse the common GlideRecord object
                gCustody.addQuery('sys_id', 'IN', manualTaskIds.join(',')); // Query for specific tasks
                gCustody.query();
                while (gCustody.next()) {
                    // Set the values for the fields to be updated
                    gCustody.setValue('state', '7'); // Set state to 'closed'
                    gCustody.active = false; // Mark task as inactive
                    gCustody.lock = false; // Unlock the task
                    gCustody.assigned_to = 'NULL'; // Clear assigned user
                    gCustody.assignment_group = 'NULL'; // Clear assignment group
                    // Perform the bulk update
                    gCustody.update();
                }
            }
            // ------Process Automated Tasks in bulk------
            if (automatedTaskIds.length > 0) {
                gCustody.initialize(); // Reuse the common GlideRecord object
                gCustody.addQuery('sys_id', 'IN', automatedTaskIds.join(',')); // Query for specific tasks
                gCustody.query();
                // Set the values for the fields to be updated
                while (gCustody.next()) {
                    gCustody.bulk_id = 'NULL'; // Clear the bulk ID
                    gCustody.setValue('state', '1');
                    gCustody.lock = false; // Unlock the task
                    gCustody.assigned_to = 'NULL'; // Clear assigned user
                    gCustody.assignment_group = 'NULL'; // Clear assignment group
                    // Perform the bulk update
                    gCustody.update();
                }
            }
            if (manualCaseIds.length > 0) {
                var gCustodyManual = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                gCustodyManual.addQuery('sys_id', 'IN', manualCaseIds.join(',')); // Query for manual cases
                gCustodyManual.query();
                while (gCustodyManual.next()) {
                    gCustodyManual.setValue('state', '3'); // Set state to 'closed'
                    gCustodyManual.active = false; // Mark case as inactive
                    gCustodyManual.update(); // Perform bulk update
                }
            }
            if (automatedCaseIds.length > 0) {
                var gCustodyAutomated = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                gCustodyAutomated.addQuery('sys_id', 'IN', automatedCaseIds.join(',')); // Query for automated cases
                gCustodyAutomated.query();
                while (gCustodyAutomated.next()) {
                    gCustodyAutomated.bulk_id = 'NULL'; // Clear the bulk ID
                    gCustodyAutomated.update(); // Perform bulk update
                }
            }
            // Update active trade count for the bulk ID and Close bulk transaction
            if (bulkID) {
                var activeTaskCount = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
                activeTaskCount.addQuery('bulk_id', bulkID); // Filter tasks by bulk ID
                activeTaskCount.addQuery('active', true); // Filter only active tasks
                activeTaskCount.addAggregate('COUNT'); // Count the number of active tasks
                activeTaskCount.query();
                if (activeTaskCount.next()) {
                    var count = parseInt(activeTaskCount.getAggregate('COUNT'), 10); // Get the count of active tasks
                    // Update the trade count in the bulk transaction
                    var gBulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
                    if (gBulk.get(bulkID)) {
                        gBulk.setValue('active_trade_count', count); // Update the active trade count
                        if (count === 0) {
                            gBulk.setValue('state', '7'); // Set state to 'Cancelled' if no active tasks remain
                        }
                        gBulk.update(); // Save the changes
                    }
                }
            }
        } catch (error) {
            gs.error("Error in RemoveMakerTask: " + error.message);
        }
    },

