    updateTaskAssignment: function(bulk_number, market) {
        var ind_task = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        //ind_task.addEncodedQuery('active=true^bulk_id!=null^bulk_id=' + bulk_number);
        ind_task.addEncodedQuery('active=true^bulk_id!=null^trade_id.owning_business=' + market + '^bulk_id=' + bulk_number);
        ind_task.query();
