    updateTaskAssignmentClient: function() {
        var userId = this.getParameter('userId');
        var bulk_id = this.getParameter('bulk_id');
        var ind_task1 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        ind_task1.addEncodedQuery('active=true^bulk_idISNOTEMPTY^bulk_id=' + bulk_id + '^stateNOT IN3,9,4');
