                            arrTradeAmend = grBulkEvents.trade_amend.toString();
                        }
                    }
                    count = ++count;
                }
                outcomearr.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend);
                if (outcomearr.indexOf('true') > -1) {
                    outcomeChk = true;
                }
            }
            if (((trdCount == 1) && (outcomearr[5].toString() == 'true')) || ((trdCount > 1) && (outcomeChk))) {
                flag = 'true';
            } else {
                flag = "Creating Bulk is not allowed as only one trade is filtered, kindly filter more trades. Amend is not applicable for the filtered Lifecycle Status.";
            }
            return flag;
        } catch (e) {
            gs.error("Unexpected error occured during Amend info message: enableFilteredParentMenu" + e.message); //MSSOTIQUBE-1096
        }
    },

    enableSelectedParentMenu: function() { //5331
        try {
            var trdCount = this.getParameter('sysparm_count');
            var query = this.getParameter('sysparm_query1');
            var trdmarket = [];
            var trdlifeStatus = [];
            var outcomearr = [];
            var outcomeChk = '';
            var count = 0;

            var grTrad = new GlideRecord("x_hsb11_mss_c_proc_custody_trades");
            grTrad.addEncodedQuery(query);
            grTrad.query();
            while (grTrad.next()) {
                trdmarket.push(grTrad.custodytrade_owning_business);
                trdlifeStatus.push(grTrad.custodytrade_trade_lifecycle_status);

            }

            // var grBulkEvents1 = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
            // grBulkEvents1.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + trdmarket + '^ctac_code=' + trdlifeStatus);
            // //grBulkEvents.orderBy(grTrdLifeCycleStatus);
            // grBulkEvents1.query();
            // if (grBulkEvents1.next()) {

            //     var amendFlag = grBulkEvents1.trade_amend;
            //     gs.info('5331 Amend flag ' + grBulkEvents1.trade_amend);
            //     if ((trdCount <= 51) && (amendFlag)) {
            //         flag = 'true';
            //     } else {
            //         flag = 'parent menu false';
            //     }
            //     gs.info('5331' + flag)
            //     return flag;
            // }
            for (var i = 0; i < trdlifeStatus.length; i++) {
                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + trdmarket[i] + '^ctac_code=' + trdlifeStatus[i]);
                //grBulkEvents.orderBy(grTrdLifeCycleStatus);
                grBulkEvents.query();
                if (grBulkEvents.next()) {
                    //flag = true;
                    if (count == 0) {
                        arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        arrResumeTrade = grBulkEvents.resume_trade.toString();
                        arrSettleTrade = grBulkEvents.settle_trade.toString();
                        arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        arrTradeAmend = grBulkEvents.trade_amend.toString();
                    } else {
                        if (grBulkEvents.confirm_trade.toString().indexOf("false") > -1) {
                            arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        }
                        if (grBulkEvents.put_trade_on_hold.toString().indexOf("false") > -1) {
                            arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        }
                        if (grBulkEvents.resume_trade.toString().indexOf("false") > -1) {
                            arrResumeTrade = grBulkEvents.resume_trade.toString();
                        }
                        if (grBulkEvents.settle_trade.toString().indexOf("false") > -1) {
                            arrSettleTrade = grBulkEvents.settle_trade.toString();
                        }
                        if (grBulkEvents.process_trade_cancellation.toString().indexOf("false") > -1) {
                            arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        }
                        if (grBulkEvents.trade_amend.toString().indexOf("false") > -1) {
                            arrTradeAmend = grBulkEvents.trade_amend.toString();
                        }
                    }
                    count = ++count;
                }
                outcomearr.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend);
                if (outcomearr.indexOf('true') > -1) {
                    outcomeChk = true;
                }
            }
            if (((trdCount == 51) && (outcomearr[5].toString() == 'true')) || ((trdCount > 51) && (outcomeChk))) {
                flag = 'true';
            } else {
                flag = "Creating Bulk is not allowed as only one trade is selected, kindly filter more trades. Amend is not applicable for the selected Lifecycle Status.";
            }
            return flag;
        } catch (e) {
            gs.error("Unexpected error occured during Amend info message: enableSelectedParentMenu" + e.message); //MSSOTIQUBE-1096
        }
    },

    //MSSCUSTODY : 6110
    getGDIFieldValue: function() {
        try {
            // Retrieve tradeID parameter
            var tradeID = this.getParameter('sysparm_tradeID');
            var taskID = this.getParameter('sysparm_taskID');

            var getTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTask.get(taskID);

            var taskStatus = getTask.active;

            if (taskStatus) {
                var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                getTradeData.get(tradeID);

                var tradeFieldName = 'gdi_indicator';
                var requestHeaderName = 'gdiIndicator';

                // Check if the field value is valid (not empty, null, or undefined)
                var fieldValue = (getTradeData.getValue(tradeFieldName) != '' &&
                        getTradeData.getValue(tradeFieldName) != null &&
                        getTradeData.getValue(tradeFieldName) != undefined) ?
                    getTradeData.getValue(tradeFieldName) :
                    '';

                // Return the JSON string directly
                return JSON.stringify({
                    [requestHeaderName]: fieldValue
                });
            } else {
                return false;
            }

        } catch (error) {
            gs.info("Error from getGDIFieldValue: " + error.message);
        }
    },

    //MSSCUSTODY-8373
    getTradesDeLink: function(bulkSysId) {
        try {
            var linkRef = '';
            var trades = [];
            var excludeTradeId = '';
            var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskGR.addQuery('bulk_id', bulkSysId);
            taskGR.addQuery('trade_task_type', 'Maker');
            taskGR.addQuery('active', true);
            taskGR.query();
            if (taskGR.next()) {
                var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                excludeTradeId = taskGR.trade_id.sys_id.toString();
                if (tradeGR.get(taskGR.trade_id)) {
                    linkRef = tradeGR.link_reference.toString();
                }
            }
            if (linkRef) {
                var eligibleTradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                eligibleTradeGR.addQuery('link_reference', linkRef);
                eligibleTradeGR.query();
                while (eligibleTradeGR.next()) {
                    // trades.push(eligibleTradeGR.sys_id.toString());
                    if (eligibleTradeGR.sys_id.toString() !== excludeTradeId) {
                        trades.push(eligibleTradeGR.sys_id.toString());
                    }
                }
                return 'sys_idIN' + trades;
            }
            return 'sys_id=NULL'; // No trades if no linkRef found
        } catch (e) {
            gs.error('Error in getTradesDeLink: ' + e.message);
        }
    },


    getScriptHoldValue: function() {
        try {
            var tradRef = this.getParameter('sysparm_tradRef');
            var txnType = this.getParameter('sysparm_txnType');
            var legacyStatus = this.getParameter('sysparm_legStatus');

            var isTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            isTrade.addQuery('legacy_status', legacyStatus);
            isTrade.addQuery('transaction_type', txnType);
            isTrade.addQuery('transaction_reference', tradRef);
            isTrade.query();

            if (isTrade.next()) {
                var holdIndicator = isTrade.script_hold_indicator.toString();
                return holdIndicator;
            }
        } catch (e) {
            gs.info('error in getscriptholdValue - Bulk Utils ' + e.message);
        }
    },

    updateAssignedTo: function() {
        try {
            var gr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            if (gr.get(this.getParameter('sysparm_sysid'))) {
                gr[this.getParameter('sysparm_field')] = this.getParameter('sysparm_value');
                return gr.update() ? 'success' : 'unsuccessful';
            }
            return 'Record not found';
        } catch (e) {
            gs.error("Could not update assignee" + e.message);
        }
    },

    updateAssignedToField: function() {
        try {
            var gr = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (gr.get(this.getParameter('sysparm_sysid'))) {
                gr[this.getParameter('sysparm_field')] = this.getParameter('sysparm_value');
                return gr.update() ? 'success' : 'unsuccessful';
            }
            return 'Record not found';
        } catch (e) {
            gs.error("Could not update assignee" + e.message);
        }
    },

